import { existsSync, readFileSync } from 'node:fs';
import { afterEach, describe, expect, it, vi } from 'vitest';
import { loadEnv } from '../env';

vi.mock('node:fs');

const existsSyncMock = vi.mocked(existsSync);
const readFileSyncMock = vi.mocked(readFileSync);
const envKeys = ['WXT_ENV_TEST_BASE', 'WXT_ENV_TEST_EXPANDED'] as const;

afterEach(() => {
  envKeys.forEach((key) => delete process.env[key]);
});

describe('Environment Utils', () => {
  describe('loadEnv', () => {
    it('loads and expands dotenv values into process.env', () => {
      existsSyncMock.mockImplementation((path) => path === '.env');
      readFileSyncMock.mockReturnValue(
        [
          'WXT_ENV_TEST_BASE=from-dotenv',
          'WXT_ENV_TEST_EXPANDED=${WXT_ENV_TEST_BASE}/expanded',
        ].join('\n'),
      );

      loadEnv('development', 'chrome');

      expect(process.env.WXT_ENV_TEST_BASE).toBe('from-dotenv');
      expect(process.env.WXT_ENV_TEST_EXPANDED).toBe(
        'from-dotenv/expanded',
      );
    });

    it('does not overwrite existing process environment variables', () => {
      process.env.WXT_ENV_TEST_BASE = 'from-process';
      existsSyncMock.mockImplementation((path) => path === '.env');
      readFileSyncMock.mockReturnValue('WXT_ENV_TEST_BASE=from-dotenv');

      loadEnv('development', 'chrome');

      expect(process.env.WXT_ENV_TEST_BASE).toBe('from-process');
    });
  });
});

